<!--
 * 站内通知发送表单组件
 *
 * @path apps/message-web/src/views/notification/notification-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：发送通知表单（NotificationSendDTO）提交 send()。
-->
<script lang="ts" setup>
/**
 * 站内通知（发送表单组件）
 * <p>消费后端契约 NotificationController#send（src/api/notification.ts，auto-generated by bash/gen-contract.py）：
 * 按 NotificationSendDTO 字段（receiverId(s)/title/content/level/category/priority/bizType 等）填写，
 * 提交成功后 emit('success') 并关闭弹窗。通知仅存在「发送」语义，无编辑。
 *
 * <p>备注：后端 @提及（mentionUserIds）仅存在于通知记录模型 MsgNotificationDTO（由评论等业务产生），
 * NotificationSendDTO 无该字段，故发送表单不提供提及输入；提及信息在列表页（index.vue）消费展示。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYdModal } from '@ydsz/common-ui';
import {
  YdForm,
  YdFormItem,
  YdInput,
  YdSelectBase,
  YdSelectContentBase,
  YdSelectItemBase,
  YdSelectTriggerBase,
  YdSelectValueBase,
  YdTextarea,
} from '@ydsz-core/ydsz-ui';
import { reactive, ref } from 'vue';

import { showToast } from '@ydsz/notification';

import { send } from '#/api/notification';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();

/** 发送通知表单状态（字段对应 NotificationSendDTO，receiverListText 拆分后映射 receiverIds） */
interface NotificationFormState {
  receiverListText: string;
  title: string;
  content: string;
  level: string;
  category: string;
  priority: string;
  senderId: string;
  bizType: string;
  actionUrl: string;
  actionText: string;
}

const formData = reactive<NotificationFormState>({
  receiverListText: '',
  title: '',
  content: '',
  level: 'INFO',
  category: '',
  priority: '',
  senderId: '',
  bizType: '',
  actionUrl: '',
  actionText: '',
});

const rules = {
  receiverListText: [{ required: true, message: '请输入接收者', trigger: 'blur' }],
  title: [{ required: true, message: '请输入标题', trigger: 'blur' }],
  content: [{ required: true, message: '请输入内容', trigger: 'blur' }],
};

/** 文本域按换行/逗号拆分接收者列表 */
function parseReceiverIds(): string[] {
  return formData.receiverListText
    .split(/[\n,;，；]/)
    .map((item) => item.trim())
    .filter((item) => item !== '');
}

const [Modal, modalApi] = useYdModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    Object.assign(formData, {
      receiverListText: '',
      title: '',
      content: '',
      level: 'INFO',
      category: '',
      priority: '',
      senderId: '',
      bizType: '',
      actionUrl: '',
      actionText: '',
    });
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      await send({
        receiverIds: parseReceiverIds(),
        title: formData.title,
        content: formData.content,
        level: formData.level || undefined,
        category: formData.category || undefined,
        priority: formData.priority || undefined,
        senderId: formData.senderId || undefined,
        bizType: formData.bizType || undefined,
        actionUrl: formData.actionUrl || undefined,
        actionText: formData.actionText || undefined,
      });
      showToast.success('通知发送成功');
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});
</script>
<template>
  <Modal :title="$t('page.notificationForm.title')">
    <YdForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <YdFormItem :label="$t('page.notificationForm.receiver')" prop="receiverListText">
        <YdTextarea
          v-model="formData.receiverListText"
          :placeholder="$t('page.notificationForm.receiverPlaceholder')"
        />
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.title')" prop="title">
        <YdInput v-model="formData.title" :placeholder="$t('page.notificationForm.titlePlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.content')" prop="content">
        <YdTextarea v-model="formData.content" :placeholder="$t('page.notificationForm.contentPlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.level')" prop="level">
        <YdSelectBase v-model="formData.level">
          <YdSelectTriggerBase>
            <YdSelectValueBase :placeholder="$t('page.notificationForm.levelPlaceholder')" />
          </YdSelectTriggerBase>
          <YdSelectContentBase>
            <YdSelectItemBase value="INFO">{{ $t('page.notificationForm.levelInfo') }}</YdSelectItemBase>
            <YdSelectItemBase value="WARN">{{ $t('page.notificationForm.levelWarn') }}</YdSelectItemBase>
            <YdSelectItemBase value="ERROR">{{ $t('page.notificationForm.levelError') }}</YdSelectItemBase>
          </YdSelectContentBase>
        </YdSelectBase>
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.category')" prop="category">
        <YdInput v-model="formData.category" :placeholder="$t('page.notificationForm.categoryPlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.priority')" prop="priority">
        <YdSelectBase v-model="formData.priority">
          <YdSelectTriggerBase>
            <YdSelectValueBase :placeholder="$t('page.notificationForm.priorityPlaceholder')" />
          </YdSelectTriggerBase>
          <YdSelectContentBase>
            <YdSelectItemBase value="HIGH">{{ $t('page.notificationForm.priorityHigh') }}</YdSelectItemBase>
            <YdSelectItemBase value="MEDIUM">{{ $t('page.notificationForm.priorityMedium') }}</YdSelectItemBase>
            <YdSelectItemBase value="LOW">{{ $t('page.notificationForm.priorityLow') }}</YdSelectItemBase>
          </YdSelectContentBase>
        </YdSelectBase>
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.bizType')" prop="bizType">
        <YdInput v-model="formData.bizType" :placeholder="$t('page.notificationForm.bizTypePlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.actionUrl')" prop="actionUrl">
        <YdInput v-model="formData.actionUrl" :placeholder="$t('page.notificationForm.actionUrlPlaceholder')" />
      </YdFormItem>
      <YdFormItem :label="$t('page.notificationForm.actionText')" prop="actionText">
        <YdInput v-model="formData.actionText" :placeholder="$t('page.notificationForm.actionTextPlaceholder')" />
      </YdFormItem>
    </YdForm>
  </Modal>
</template>
